module main_sram0_mux (
    input  wire clk,
    input  wire rst_n,

    // master side, one entry per connected master port (index 0 = highest priority)
    input  wire [2:0][31:0] m_haddr,
    input  wire [2:0] m_hwrite,
    input  wire [2:0][1:0] m_htrans,
    input  wire [2:0][2:0] m_hsize,
    input  wire [2:0][31:0] m_hwdata,
    output wire [2:0][31:0] m_hrdata,
    output wire [2:0] m_hready,
    output wire [2:0] m_hresp,
    output wire [2:0] m_gnt,  // m_gnt[i]: master i's request is passed to the slave this cycle

    // slave side (to sram0)
    output wire [31:0] s_haddr,
    output wire s_hwrite,
    output wire [1:0] s_htrans,
    output wire [2:0] s_hsize,
    output wire [31:0] s_hwdata,
    input  wire [31:0] s_hrdata,
    input  wire s_hready,
    input  wire s_hresp
);

    // Name for the position of each entry
    localparam PPU0_OAM = 0;  // ppu0.oam (ppu)
    localparam CORE0_DATA = 1;  // core0.data (hazard3_cpu_2port)
    localparam CORE0_INSTRUCTION = 2;  // core0.instruction (hazard3_cpu_2port)

    // Signals shared by the parts below
    wire [2:0] req;     // request of each master
    wire [2:0] pick;    // winning master: one-hot, or zero when nobody requests
    reg  [2:0] dgnt_r;  // master owning the data phase

    // Arbiter: which master gets the slave this cycle
    // request bits: the master drives the transfer select
    assign req[PPU0_OAM] = m_htrans[PPU0_OAM][1];
    assign req[CORE0_DATA] = m_htrans[CORE0_DATA][1];
    assign req[CORE0_INSTRUCTION] = m_htrans[CORE0_INSTRUCTION][1];
    // pick: the lowest-numbered requesting master wins
    assign pick[PPU0_OAM] = req[PPU0_OAM];
    assign pick[CORE0_DATA] = req[CORE0_DATA] & ~(|req[0:0]);
    assign pick[CORE0_INSTRUCTION] = req[CORE0_INSTRUCTION] & ~(|req[1:0]);
    // grant: the pick, when the slave can accept
    assign m_gnt = pick & {3{s_hready}};

    // Registered grant: the master that owns the data phase
