    assign s_haddr  = ({32{pick[PPU0_OAM]}} & m_haddr[PPU0_OAM]) |
        ({32{pick[CORE0_DATA]}} & m_haddr[CORE0_DATA]) |
        ({32{pick[CORE0_INSTRUCTION]}} & m_haddr[CORE0_INSTRUCTION]);
    assign s_hwrite = (pick[PPU0_OAM] & m_hwrite[PPU0_OAM]) |
        (pick[CORE0_DATA] & m_hwrite[CORE0_DATA]) |
        (pick[CORE0_INSTRUCTION] & m_hwrite[CORE0_INSTRUCTION]);
    assign s_htrans = s_hready ? (({2{pick[PPU0_OAM]}} & m_htrans[PPU0_OAM]) |
        ({2{pick[CORE0_DATA]}} & m_htrans[CORE0_DATA]) |
        ({2{pick[CORE0_INSTRUCTION]}} & m_htrans[CORE0_INSTRUCTION])) : 2'b0;
    assign s_hsize  = ({3{pick[PPU0_OAM]}} & m_hsize[PPU0_OAM]) |
        ({3{pick[CORE0_DATA]}} & m_hsize[CORE0_DATA]) |
        ({3{pick[CORE0_INSTRUCTION]}} & m_hsize[CORE0_INSTRUCTION]);
    assign s_hwdata = ({32{dgnt_r[PPU0_OAM]}} & m_hwdata[PPU0_OAM]) |
        ({32{dgnt_r[CORE0_DATA]}} & m_hwdata[CORE0_DATA]) |
        ({32{dgnt_r[CORE0_INSTRUCTION]}} & m_hwdata[CORE0_INSTRUCTION]);

    // Response path: fanned out to every master
    assign m_hrdata = {3{s_hrdata}};
